import assert from 'node:assert/strict';
import test from 'node:test';

import { loadSupportInstructions, runSupportAgent } from './support-agent.js';

test('loads the canonical instruction for both Responses calls', async () => {
  const requests = [];
  const responsesClient = {
    responses: {
      create: async (request) => {
        requests.push(request);
        return { id: `response-${requests.length}` };
      },
    },
  };

  await runSupportAgent(responsesClient, 'Where is order 123?');
  const canonicalInstruction = await loadSupportInstructions();

  assert.equal(requests.length, 2);
  assert.equal(requests[0].instructions, canonicalInstruction);
  assert.equal(requests[0].instructions, requests[1].instructions);
  assert.match(canonicalInstruction, /^`customer-support`\n/);
});

